import{_ as n,a0 as s,w as l,s as a,ao as p,I as m,x as i,a1 as e,A as o}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const C=JSON.parse('{"title":"Vim 起步的五个技巧 | LCTT x X-CMD","titleTemplate":false,"description":"Vim 起步的五个技巧 | LCTT (201608) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"Vim 起步的五个技巧 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"Vim 起步的五个技巧 | LCTT (201608) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201608/20160721 5 tricks for getting started with Vim","title":"Vim 起步的五个技巧","tag":"201608","desc":""},"relativePath":"201608/20160721 5 tricks for getting started with Vim.md","filePath":"[post].md"}'),u={name:"201608/20160721 5 tricks for getting started with Vim.md"};function d(V,t,f,g,T,v){const r=s("Link");return l(),a("div",null,[t[23]||(t[23]=p('<h1 id="vim-起步的五个技巧" tabindex="-1">Vim 起步的五个技巧 <a class="header-anchor" href="#vim-起步的五个技巧" aria-label="Permalink to “Vim 起步的五个技巧”">​</a></h1><p><img src="https://opensource.com/sites/default/files/styles/image-full-size/public/images/education/BUSINESS_peloton.png?itok=nuMbW9d3" alt=""></p><p>多年来，我一直想学 Vim。如今 Vim 是我最喜欢的 Linux 文本编辑器，也是开发者和系统管理者最喜爱的开源工具。我说的学习，指的是真正意义上的学习。想要精通确实很难，所以我只想要达到熟练的水平。我使用了这么多年的 Linux ，我会的也仅仅只是打开一个文件，使用上下左右箭头按键来移动光标，切换到插入模式，更改一些文本，保存，然后退出。</p><p>但那只是 Vim 的最最基本的操作。我的技能水平只能让我在终端使用 Vim 修改文本，但是它并没有任何一个我想象中强大的文本处理功能。这样我完全无法用 Vim 发挥出胜出 Pico 和 Nano 的能力。</p><p>所以到底为什么要学习 Vim？因为我花费了相当多的时间用于编辑文本，而且我知道还有很大的效率提升空间。为什么不选择 Emacs，或者是更为现代化的编辑器例如 Atom？因为 Vim 适合我，至少我有一丁点的使用经验。而且，很重要的一点就是，在我需要处理的系统上很少碰见没有装 Vim 或者它的弱化版（Vi）。如果你有强烈的欲望想学习对你来说更给力的 Emacs，我希望这些对于 Emacs 同类编辑器的建议能对你有所帮助。</p><p>花了几周的时间专注提高我的 Vim 使用技巧之后，我想分享的第一个建议就是必须使用它。虽然这看起来就是明知故问的回答，但事实上它比我所预想的计划要困难一些。我的大多数工作是在网页浏览器上进行的，而且每次我需要在浏览器之外打开并编辑一段文本时，就需要避免下意识地打开 Gedit。Gedit 已经放在了我的快速启动栏中，所以第一步就是移除这个快捷方式，然后替换成 Vim 的。</p><p>为了更好的学习 Vim，我尝试了很多。如果你也正想学习，以下列举了一些作为推荐。</p><h3 id="vimtutor" tabindex="-1">Vimtutor <a class="header-anchor" href="#vimtutor" aria-label="Permalink to “Vimtutor”">​</a></h3><p>通常如何开始学习最好就是使用应用本身。我找到一个小的应用叫 Vimtutor，当你在学习编辑一个文本时它能辅导你一些基础知识，它向我展示了很多我这些年都忽视的基础命令。Vimtutor 一般在有 Vim 的地方都能找到它，如果你的系统上没有 Vimtutor，Vimtutor 可以很容易从你的包管理器上安装。</p><h3 id="gvim" tabindex="-1">GVim <a class="header-anchor" href="#gvim" aria-label="Permalink to “GVim”">​</a></h3><p>我知道并不是每个人都认同这个，但就是它让我从使用终端中的 Vim 转战到使用 GVim 来满足我基本编辑需求。反对者表示 GVim 鼓励使用鼠标，而 Vim 主要是为键盘党设计的。但是我能通过 GVim 的下拉菜单快速找到想找的指令，并且 GVim 可以提醒我正确的指令然后通过敲键盘执行它。努力学习一个新的编辑器然后陷入无法解决的困境，这种感觉并不好受。每隔几分钟读一下 man 出来的文字或者使用搜索引擎来提醒你该用的按键序列也并不是最好的学习新事物的方法。</p><h3 id="键盘表" tabindex="-1">键盘表 <a class="header-anchor" href="#键盘表" aria-label="Permalink to “键盘表”">​</a></h3><p>当我转战 GVim，我发现有一个键盘的“速查表”来提醒我最基础的按键很是便利。网上有很多这种可用的表，你可以下载、打印，然后贴在你身边的某一处地方。但是为了我的笔记本键盘，我选择买一沓便签纸。这些便签纸在美国不到 10 美元，当我使用键盘编辑文本，尝试新的命令的时候，可以随时提醒我。</p><h3 id="vimium" tabindex="-1">Vimium <a class="header-anchor" href="#vimium" aria-label="Permalink to “Vimium”">​</a></h3>',14)),m("p",null,[t[2]||(t[2]=i("上文提到，我工作都在浏览器上进行。其中一条我觉得很有帮助的建议就是，使用 ",-1)),e(r,{href:"https://github.com/philc/vimium"},{default:o(()=>[...t[0]||(t[0]=[i("Vimium",-1)])]),_:1}),t[3]||(t[3]=i(" 来用增强使用 Vim 的体验。Vimium 是 Chrome 浏览器上的一个开源插件，能用 Vim 的指令快捷操作 Chrome。我发现我只用了几次使用快捷键切换上下文，就好像比之前更熟悉这些快捷键了。同样的扩展 Firefox 上也有，例如 ",-1)),e(r,{href:"http://www.vimperator.org/"},{default:o(()=>[...t[1]||(t[1]=[i("Vimerator",-1)])]),_:1}),t[4]||(t[4]=i("。",-1))]),t[24]||(t[24]=m("h3",{id:"其它人",tabindex:"-1"},[i("其它人 "),m("a",{class:"header-anchor",href:"#其它人","aria-label":"Permalink to “其它人”"},"​")],-1)),t[25]||(t[25]=m("p",null,"毫无疑问，最好的学习方法就是求助于在你之前探索过的人，让他给你建议、反馈和解决方法。",-1)),t[26]||(t[26]=m("p",null,"如果你住在一个大城市，那么附近可能会有一个 Vim meetup 小组，或者还有 Freenode IRC 上的 #vim 频道。#vim 频道是 Freenode 上最活跃的频道之一，那上面可以针对你个人的问题来提供帮助。听上面的人发发牢骚或者看看别人尝试解决自己没有遇到过的问题，仅仅是这样我都觉得很有趣。",-1)),t[27]||(t[27]=m("hr",null,null,-1)),t[28]||(t[28]=m("p",null,"那么，现在怎么样了？到现在为止还不错。为它所花的时间是否值得就在于之后它为你节省了多少时间。但是当我发现一个新的按键序列可以来跳过词，或者一些相似的小技巧，我经常会收获意外的惊喜与快乐。每天我至少可以看见，一点点的回报，正在逐渐配得上当初的付出。",-1)),m("p",null,[t[7]||(t[7]=i("学习 Vim 并不仅仅只有这些建议，还有很多。我很喜欢指引别人去 ",-1)),e(r,{href:"http://vim-adventures.com/"},{default:o(()=>[...t[5]||(t[5]=[i("Vim Advantures",-1)])]),_:1}),t[8]||(t[8]=i("，它是一种使用 Vim 按键方式进行移动的在线游戏。而在另外一天我在 ",-1)),e(r,{href:"http://vimgifs.com/"},{default:o(()=>[...t[6]||(t[6]=[i("Vimgifts.com",-1)])]),_:1}),t[9]||(t[9]=i(" 发现了一个非常神奇的虚拟学习工具，那可能就是你真正想要的：用一个小小的 gif 动图来描述 Vim 操作。",-1))]),t[29]||(t[29]=m("p",null,"你有花时间学习 Vim 吗？或者是任何需要大量键盘操作的程序？那些经过你努力后掌握的工具，你认为这些努力值得吗？效率的提高有没有达到你的预期？分享你们的故事在下面的评论区吧。",-1)),t[30]||(t[30]=m("hr",null,null,-1)),m("p",null,[t[11]||(t[11]=i("via: ",-1)),e(r,{href:"https://opensource.com/life/16/7/tips-getting-started-vim"},{default:o(()=>[...t[10]||(t[10]=[i("https://opensource.com/life/16/7/tips-getting-started-vim",-1)])]),_:1})]),m("p",null,[t[15]||(t[15]=i("作者：",-1)),e(r,{href:"https://opensource.com/users/jason-baker"},{default:o(()=>[...t[12]||(t[12]=[i("Jason Baker",-1)])]),_:1}),t[16]||(t[16]=i(" 译者：",-1)),e(r,{href:"https://github.com/maywanting"},{default:o(()=>[...t[13]||(t[13]=[i("maywanting",-1)])]),_:1}),t[17]||(t[17]=i(" 校对：",-1)),e(r,{href:"https://github.com/wxy"},{default:o(()=>[...t[14]||(t[14]=[i("wxy",-1)])]),_:1})]),m("p",null,[t[20]||(t[20]=i("本文由 ",-1)),e(r,{href:"https://github.com/LCTT/TranslateProject"},{default:o(()=>[...t[18]||(t[18]=[i("LCTT",-1)])]),_:1}),t[21]||(t[21]=i(" 原创编译，",-1)),e(r,{href:"https://linux.cn/"},{default:o(()=>[...t[19]||(t[19]=[i("Linux中国",-1)])]),_:1}),t[22]||(t[22]=i(" 荣誉推出",-1))])])}const k=n(u,[["render",d]]);export{C as __pageData,k as default};
